def unhappyFriends(n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
    # Step 1: Preprocess preferences for faster lookup
    rank = [{} for _ in range(n)]
    for i in range(n):
        for idx, friend in enumerate(preferences[i]):
            rank[i][friend] = idx

    # Step 2: Create a mapping of current pairs
    pair_map = {}
    for x, y in pairs:
        pair_map[x] = y
        pair_map[y] = x

    # Step 3: Check for unhappiness
    unhappy = set()
    for x in range(n):
        y = pair_map[x]
        # Get the rank of y in x's preference list
        y_rank = rank[x][y]
        # Iterate through all friends u who are preferred over y
        for u in preferences[x][:y_rank]:
            v = pair_map[u]
            # Check if u prefers x over v
            if rank[u][x] < rank[u][v]:
                unhappy.add(x)
                break

    # Step 4: Return the count of unhappy friends
    return len(unhappy)

