def minSwaps(grid: List[List[int]]) -> int:
    n = len(grid)
    # Step 1: Calculate the required trailing zeros for each row
    required = [n - i - 1 for i in range(n)]

    # Step 2: Calculate the actual trailing zeros for each row
    actual = []
    for row in grid:
        count = 0
        for j in range(n - 1, -1, -1):
            if row[j] == 0:
                count += 1
            else:
                break
        actual.append(count)

    # Step 3: Sort the actual trailing zeros in descending order
    sorted_actual = sorted(actual, reverse=True)

    # Step 4: Check feasibility
    for i in range(n):
        if sorted_actual[i] < required[i]:
            return -1

    # Step 5: Calculate the minimum swaps
    swaps = 0
    for i in range(n):
        # Find the row with the required trailing zeros
        for j in range(i, n):
            if actual[j] >= required[i]:
                # Swap rows from i to j
                for k in range(j, i, -1):
                    actual[k], actual[k - 1] = actual[k - 1], actual[k]
                    swaps += 1
                break

    # Step 6: Return the total number of swaps
    return swaps

