import math

def leastOpsExpressTarget(x: int, target: int) -> int:
    memo = {}

    def dp(k, target):
        if (k, target) in memo:
            return memo[(k, target)]

        if target == 0:
            return 0

        if k == 0:
            return 2 * (target - 1)

        power = x ** k
        c = target // power
        r = target % power

        # Option 1: use c times x^k and then handle remainder
        option1 = c * k + dp(k - 1, r)

        # Option 2: use (c + 1) times x^k and then handle the excess
        option2 = (c + 1) * k + dp(k - 1, power - r)

        res = min(option1, option2)
        memo[(k, target)] = res
        return res

    max_k = 0
    if x == 1:
        max_k = target
    else:
        max_k = math.floor(math.log(target, x)) + 1

    min_ops = float('inf')
    for k in range(0, max_k + 1):
        ops = dp(k, target)
        if ops < min_ops:
            min_ops = ops

    return min_ops

